select case when cost >= 99 then 'PREMIUM' else 'STANDARD' end as cost_tier, avg(cost) as avg_cost, count_if(status = 'DELIVERED') as delivered_events, count(*) filter (where status = 'DELIVERED') as delivered_rows, stddev_samp(cost) as cost_stddev, count_if(carrier = 'UPS') as ups_events, approx_percentile(cost, 0.95) as cost_p95 from shipments group by 1 order by delivered_rows nulls last;
